    "O aplicativo continua ativo enquanto os indicadores são preparados.": "La aplicación permanece activa mientras se preparan los indicadores.",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "El archivo exportado contiene la contraseña APRS-IS en texto legible. Guárdelo en un lugar seguro.",
