    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "El cliente no asigna un modelo de radio basándose únicamente en el chipset USB. Cuando Windows no informa el modelo real, la interfaz se muestra de forma genérica, por ejemplo.",
    "O compositor aceita mensagens longas. Use": "El compositor acepta mensajes largos.",
    "O destino deixou de possuir rota RF completa no período selecionado.": "El destino ya no tiene una ruta RF completa durante el período seleccionado.",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi utiliza supresión de duplicados, bloqueo de bucles, limitación de saltos y una cola de prioridad para los mensajes/ACK/REJ.",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "El filtro APRS-IS está vacío. Dependiendo del servidor y el puerto utilizados, el cliente podría recibir un volumen de tráfico mucho mayor, incluyendo todo el flujo disponible en esta conexión.\n\n¿Desea continuar sin filtro?",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "El gráfico utiliza mensajes, ACK/REJ, y presencia, RF, para priorizar el tráfico útil y evitar repeticiones innecesarias. No reescribe arbitrariamente rutas de terceros ni inventa enlaces, RF.",
