    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "El estándar para nuevas instalaciones recibe identificadores brasileños. El campo permanece totalmente editable para los filtros APRS-IS manuais.",
