    "PY2AAA-9, PU2BBB-7, PT2CCC": "PY2AAA-9, PU2BBB-7, PT2CCC",
    "Quando chega uma nova mensagem para sua estação e a aba Mensagens já está aberta, o programa usa um aviso pequeno e não bloqueante, que fecha automaticamente pelo tempo definido em Configuração. Fora da aba Mensagens, permanece o aviso completo com opção de responder.": "Cuando llega un nuevo mensaje a tu estación y la pestaña Mensajes ya está abierta, el programa utiliza una pequeña notificación que no bloquea la aplicación y que se cierra automáticamente después del tiempo definido en la configuración. Fuera de la pestaña Mensajes, la notificación completa permanece visible con la opción de responder.",
    "Quando houver atualização, clicar no aviso inicia o download do pacote compatível com a plataforma. O arquivo é validado antes da instalação.": "Cuando haya una actualización disponible, al hacer clic en la notificación se iniciará la descarga del paquete compatible con su plataforma. El archivo se valida antes de la instalación.",
    "Quando houver nova versão, o cliente seleciona o pacote compatível com a plataforma, valida o download e usa um updater auxiliar para encerrar a versão atual, instalar e abrir a nova versão.": "Cuando hay una nueva versión disponible, el cliente selecciona el paquete compatible con la plataforma, valida la descarga y utiliza un actualizador auxiliar para cerrar la versión actual, instalarla y abrir la nueva versión.",
    "quando necessário. A configuração oferece sugestões regionais e continua aceitando servidor manual.": "cuando sea necesario. La configuración ofrece sugerencias de regionais y continúa aceptando configuraciones manuales del servidor.",
