    "A alteração é aplicada imediatamente e fica salva após clicar em Salvar.": "La modification est appliquée immédiatement et enregistrée après avoir cliqué sur Enregistrer.",
    "A altitude ainda está em 0 m porque não foi obtida automaticamente. O beacon será enviado, mas recomendamos informar a altitude real.": "L'altitude est toujours à 0 m car elle n'a pas été mesurée automatiquement. La balise sera envoyée, mais nous vous recommandons de communiquer l'altitude réelle.",
    "A atualização está em andamento. Aguarde a conclusão.": "La mise à jour est en cours. Veuillez patienter jusqu'à la fin.",
    "A cadeia representa alcançabilidade RF histórica composta por enlaces observados individualmente e compatíveis pelas coordenadas dos nós.": "La chaîne représente l'accessibilité historique composée de liens observés individuellement et compatibles par les coordonnées des nœuds.",
    "A camada mostra apenas terreno com altitude igual ou superior à cota escolhida no slider.": "Cette couche n'affiche que les terrains dont l'altitude est égale ou supérieure à l'altitude sélectionnée par le curseur.",
    "A lista mostra indicativo, última recepção, distância, velocidade, curso, altitude e informações conhecidas.": "La liste indique l'indicatif d'appel, la dernière information reçue, la distance, la vitesse, le cap, l'altitude et les informations connues.",
    "A malha é muito densa e a busca atingiu o limite de segurança. Os enlaces elegíveis continuam visíveis; refine o período se precisar de mais rotas.": "Le réseau est très dense et la recherche a atteint sa limite de sécurité. Les liens disponibles restent visibles ; affinez la période si vous avez besoin de plus d’itinéraires.",
    "A mensagem já está sendo colocada na fila.": "Le message est déjà en attente.",
    "A string contém componentes ainda não representados no editor. Eles serão preservados enquanto você não gerar uma nova string.": "La chaîne contient des éléments qui ne sont pas encore présents dans l'éditeur. Ils seront conservés jusqu'à la génération d'une nouvelle chaîne.",
