    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "Les nouvelles installations utilisent par défaut les préfixes brésiliens. L'éditeur graphique permet de combiner des filtres pour le Brésil, le rayon, la zone géographique, les préfixes, les indicatifs d'appel exacts et les types de paquets, tout en laissant le champ manuel toujours accessible.",
    "novo": "nouveau",
    "Novo destinatário: __ARG0__. Ainda não há conversa registrada com este indicativo.": "Nouveau destinataire : __ARG0__. Aucune conversation n'a encore été enregistrée avec cette adresse.",
    "O aplicativo continua ativo enquanto os indicadores são preparados.": "L'application reste active pendant la préparation des indicateurs.",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Le fichier exporté contient le code d'accès APRS-IS en texte clair. Conservez-le en lieu sûr.",
    "O banco SQLite fica em:": "La base de données SQLite se trouve à l'emplacement suivant :",
    "O botão": "Le bouton",
    "O cabeçalho informa se você está usando a": "L'en-tête vous indique si vous utilisez le",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "Le client n'attribue pas de modèle radio uniquement en fonction du chipset USB. Lorsque Windows ne détecte pas le modèle réel, l'interface affiche un affichage générique, par exemple.",
    "O compositor aceita mensagens longas. Use": "Le compositeur accepte les messages longs. Utilisez",
    "O destino deixou de possuir rota RF completa no período selecionado.": "La destination ne dispose plus d'un itinéraire RF complet pendant la période sélectionnée.",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi utilise la suppression des doublons, le blocage des boucles, la limitation du nombre de sauts et une file d'attente prioritaire pour les messages/ACK/REJ.",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "Le filtre APRS-IS est vide. Selon le serveur et le port utilisés, le client peut recevoir un volume de trafic beaucoup plus important, voire la totalité du flux disponible sur cette connexion.\n\nVoulez-vous continuer sans filtre ?",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "Le graphe utilise les messages (ACK/REJ) et la présence (RF) pour prioriser le trafic utile et éviter les répétitions inutiles. Il ne réécrit pas arbitrairement les chemins tiers ni n'invente de liens (RF).",
    "O idioma é aplicado imediatamente à interface.": "Le langage est immédiatement appliqué à l'interface TECH0__ace.",
    "O início precisa ser anterior ao fim.": "Le début doit précéder la fin.",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "Le programme d'installation et le fichier EXE portable utilisent la même base de données locale.",
    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Le fichier exporté JSON contient le code d'accès APRS-IS en texte lisible. Conservez-le en lieu sûr.",
    "O novo cálculo falhou; mantendo o último ranking válido.": "Le nouveau calcul a échoué ; le dernier classement reste valable.",
    "O pacote compatível será baixado, validado e instalado automaticamente.": "Le package compatible sera téléchargé, validé et installé automatiquement.",
    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "La norme pour les nouvelles installations reçoit des identifiants brésiliens. Le champ reste entièrement modifiable pour les filtres APRS-IS manuais.",
    "O passcode é mascarado no Log.": "Le code d'accès est masqué dans le journal.",
