    "para nova linha. Mensagens maiores são divididas automaticamente sem numeração visível, preservando palavras sempre que possível; cada parte mantém confirmação própria.": "Pour un saut de ligne. Les messages plus longs sont automatiquement coupés sans numérotation visible, en conservant les mots autant que possible ; chaque partie conserve sa propre confirmation.",
