    "podem ser informadas em decimal ou graus/minutos/segundos. Na primeira execução, o cliente solicita a localização ao navegador/SO para pré-preencher as coordenadas e centralizar o mapa. O botão": "Les valeurs peuvent être saisies au format décimal ou en degrés/minutes/secondes. Lors du premier lancement, le client demande la position au navigateur/système d'exploitation afin de préremplir les coordonnées et de centrer la carte. Le bouton",
