    "publicada.": "Publié.",
    "PY2AAA-9, PU2BBB-7, PT2CCC": "PY2AAA-9, PU2BBB-7, PT2CCC",
    "Quando chega uma nova mensagem para sua estação e a aba Mensagens já está aberta, o programa usa um aviso pequeno e não bloqueante, que fecha automaticamente pelo tempo definido em Configuração. Fora da aba Mensagens, permanece o aviso completo com opção de responder.": "Lorsqu'un nouveau message arrive pour votre station et que l'onglet Messages est déjà ouvert, le programme affiche une petite notification non bloquante qui se ferme automatiquement après le délai défini dans les paramètres. En dehors de l'onglet Messages, la notification complète reste visible et vous pouvez y répondre.",
    "Quando houver atualização, clicar no aviso inicia o download do pacote compatível com a plataforma. O arquivo é validado antes da instalação.": "Lorsqu'une mise à jour est disponible, cliquer sur la notification lancera le téléchargement du package compatible avec votre plateforme. Le fichier est validé avant l'installation.",
    "Quando houver nova versão, o cliente seleciona o pacote compatível com a plataforma, valida o download e usa um updater auxiliar para encerrar a versão atual, instalar e abrir a nova versão.": "Lorsqu'une nouvelle version est disponible, le client sélectionne le package compatible avec la plateforme, valide le téléchargement et utilise un programme de mise à jour auxiliaire pour fermer la version actuelle, installer et ouvrir la nouvelle version.",
    "quando necessário. A configuração oferece sugestões regionais e continua aceitando servidor manual.": "en cas de besoin. La configuration propose des suggestions pour la région TECH0 et continue d'accepter les paramètres manuels du serveur.",
    "quando usado pela serial neste fluxo, mantenha o rádio no modo": "Lors de l'utilisation de la communication série dans ce flux, maintenez la radio en mode.",
