    "Ranking único de estações comuns. Telemetria, iGates e digipeaters são excluídos; interações consideram somente conversas APRS manuais.": "Classement unique des stations communes. La télémétrie, iGates et digipeaters sont exclues ; les interactions ne prennent en compte que les conversations APRS et ais.",
