    ", informe seu indicativo, SSID, posição e parâmetros APRS-IS. O passcode é calculado automaticamente a partir do indicativo-base.": "Bitte geben Sie Ihr Rufzeichen SSID, Ihre Position und die Parameter APRS-IS an. Der Passcode wird automatisch aus dem Basisrufzeichen berechnet.",
