    ". O path RF personalizado aceita valores como": "Der benutzerdefinierte Pfad RF akzeptiert Werte wie beispielsweise",
    ". Quando o trace retornar um caminho e houver posições conhecidas, os hops são destacados temporariamente no mapa; hops sem posição continuam indicados na resposta sem localização inventada.": "Wenn die Ablaufverfolgung einen Pfad zurückgibt und bekannte Positionen vorhanden sind, werden die Hops vorübergehend auf der Karte hervorgehoben; Hops ohne Position bleiben in der Antwort ohne erfundenen Standort angegeben.",
