    "A alteração é aplicada imediatamente e fica salva após clicar em Salvar.": "Die Änderung wird sofort angewendet und nach dem Klicken auf „Speichern“ gespeichert.",
    "A altitude ainda está em 0 m porque não foi obtida automaticamente. O beacon será enviado, mas recomendamos informar a altitude real.": "Die Höhe wird weiterhin mit 0 m angezeigt, da sie nicht automatisch ermittelt wurde. Das Notsignal wird gesendet, wir empfehlen jedoch, die tatsächliche Höhe zu melden.",
    "A atualização está em andamento. Aguarde a conclusão.": "Das Update wird gerade durchgeführt. Bitte warten Sie, bis es abgeschlossen ist.",
    "A cadeia representa alcançabilidade RF histórica composta por enlaces observados individualmente e compatíveis pelas coordenadas dos nós.": "Die Kette stellt die historische Erreichbarkeit dar, die aus einzeln betrachteten Verbindungen besteht und durch die Koordinaten der Knoten miteinander kompatibel ist.",
    "A camada mostra apenas terreno com altitude igual ou superior à cota escolhida no slider.": "Die Ebene zeigt nur Gelände mit einer Höhe an, die gleich oder größer als die im Schieberegler ausgewählte Höhe ist.",
    "A lista mostra indicativo, última recepção, distância, velocidade, curso, altitude e informações conhecidas.": "Die Liste zeigt das Rufzeichen, den zuletzt empfangenen Zeitpunkt, die Entfernung, die Geschwindigkeit, den Kurs, die Höhe und bekannte Informationen an.",
    "A malha é muito densa e a busca atingiu o limite de segurança. Os enlaces elegíveis continuam visíveis; refine o período se precisar de mais rotas.": "Das Netzwerk ist sehr dicht, und die Suche hat die Sicherheitsgrenze erreicht. Geeignete Verbindungen bleiben sichtbar; verfeinern Sie den Zeitraum, falls Sie weitere Routen benötigen.",
    "A mensagem já está sendo colocada na fila.": "Die Nachricht befindet sich bereits in der Warteschlange.",
    "A string contém componentes ainda não representados no editor. Eles serão preservados enquanto você não gerar uma nova string.": "Die Zeichenkette enthält Komponenten, die im Editor noch nicht dargestellt sind. Diese bleiben erhalten, bis Sie eine neue Zeichenkette generieren.",
    "A topologia oferece período": "Die Topologie bietet einen Zeitraum.",
    "Abrir Configuração": "Einstellungen öffnen",
