    "Alterações de transporte reconectam o TNC se ele já estiver em uso. Ativar funções de TX exige a confirmação explícita acima.": "Transportänderungen stellen die Verbindung zu TNC wieder her, falls diese bereits belegt ist. Die Aktivierung von TX-Funktionen erfordert eine explizite Bestätigung (siehe oben).",
