    "Apagar TODAS as mensagens e boletins armazenados neste computador? Somente o histórico local de mensagens será removido. Esta ação não pode ser desfeita.": "Alle auf diesem Computer gespeicherten Nachrichten und Mitteilungen löschen? Es wird lediglich der lokale Nachrichtenverlauf entfernt. Diese Aktion kann nicht rückgängig gemacht werden.",
