    "Na primeira execução, quando a permissão é concedida, o mapa é centralizado na localização atual do usuário. Depois disso, a posição e o zoom escolhidos manualmente ficam salvos localmente e não são recentralizados continuamente.": "Beim ersten Start, sobald die Berechtigung erteilt wurde, wird die Karte auf den aktuellen Standort des Nutzers zentriert. Danach werden die manuell gewählte Position und der Zoom lokal gespeichert und nicht ständig neu ausgerichtet.",
