    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "Neuinstallationen verwenden standardmäßig brasilianische Vorwahlen. Der grafische Editor kann Filter für Brasilien, Radius, geografisches Gebiet, Vorwahlen, exakte Rufzeichen und Pakettypen kombinieren, wobei das manuelle Eingabefeld stets verfügbar bleibt.",
    "novo": "neu",
    "Novo destinatário: __ARG0__. Ainda não há conversa registrada com este indicativo.": "Neuer Empfänger: __ARG0__. Es sind noch keine Konversationen mit dieser Adresse aufgezeichnet.",
    "O aplicativo continua ativo enquanto os indicadores são preparados.": "Die Anwendung bleibt aktiv, während die Indikatoren vorbereitet werden.",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Die exportierte Datei enthält den Passcode APRS-IS im lesbaren Textformat. Bewahren Sie sie an einem sicheren Ort auf.",
    "O banco SQLite fica em:": "Die SQLite-Datenbank befindet sich hier:",
    "O botão": "Der Knopf",
    "O cabeçalho informa se você está usando a": "Die Kopfzeile zeigt Ihnen an, ob Sie die",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "Der Client ordnet kein Funkmodell allein anhand des USB-Chipsatzes zu. Wenn Windows das tatsächliche Modell nicht meldet, wird beispielsweise eine generische Schnittstelle angezeigt.",
    "O compositor aceita mensagens longas. Use": "Der Komponist akzeptiert lange Nachrichten.",
    "O destino deixou de possuir rota RF completa no período selecionado.": "Für das Ziel gibt es im ausgewählten Zeitraum keine vollständige RF Route mehr.",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi verwendet Duplikatunterdrückung, Schleifenblockierung, Hop-Limitierung und eine Prioritätswarteschlange für Nachrichten/ACK/REJ.",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "Der Filter APRS-IS ist leer. Je nach verwendetem Server und Port kann der Client ein deutlich höheres Datenaufkommen empfangen, einschließlich des gesamten über diese Verbindung verfügbaren Datenflusses.\n\nMöchten Sie ohne Filter fortfahren?",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "Der Graph verwendet Nachrichten (ACK/REJ) und Präsenzinformationen (RF), um relevanten Datenverkehr zu priorisieren und unnötige Wiederholungen zu vermeiden. Er ändert keine Pfade von Drittanbietern willkürlich und erfindet keine Links (RF).",
    "O idioma é aplicado imediatamente à interface.": "Die Sprache wird sofort auf interface angewendet.",
    "O início precisa ser anterior ao fim.": "Der Anfang muss vor dem Ende kommen.",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "Das Installationsprogramm und die portable EXE-Datei verwenden dieselbe lokale Datenbank.",
    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Die exportierte Datei JSON enthält den Passcode APRS-IS in lesbarem Text. Bewahren Sie sie an einem sicheren Ort auf.",
    "O novo cálculo falhou; mantendo o último ranking válido.": "Die Neuberechnung ist fehlgeschlagen; die letzte Rangliste bleibt gültig.",
    "O pacote compatível será baixado, validado e instalado automaticamente.": "Das kompatible Paket wird automatisch heruntergeladen, validiert und installiert.",
    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "Der Standard für Neuinstallationen erhält brasilianische Kennungen. Das Feld bleibt für die Filter APRS-IS und ais vollständig editierbar.",
    "O passcode é mascarado no Log.": "Der Passcode ist im Protokoll maskiert.",
    "o popup da estação inclui atalhos para consultar": "Das Stations-Popup enthält Verknüpfungen zum Konsultieren.",
    "O servidor padrão é": "Der Standardserver ist",
    "O servidor retornou um backup vazio.": "Der Server hat ein leeres Backup zurückgegeben.",
    "O trecho permanece inferido; o software não inventa estações para preencher a rota.": "Der Streckenabschnitt bleibt implizit; die Software erfindet keine Stationen, um die Route zu vervollständigen.",
