    "Os títulos das colunas podem ser clicados para alterar a ordenação. Estações favoritas ficam fixadas no topo e são identificadas por uma estrela amarela.": "Durch Anklicken der Spaltenüberschriften lässt sich die Sortierung ändern. Lieblingssender sind oben angeheftet und mit einem gelben Stern gekennzeichnet.",
