    "para móvel.": "Für Mobilgeräte.",
    "para não impedir a conexão e mostra um aviso recomendando informar a altitude real.": "Um die Verbindung nicht zu unterbrechen, wird eine Warnung angezeigt, die empfiehlt, Ihre tatsächliche Höhe einzugeben.",
    "para nova linha. Mensagens maiores são divididas automaticamente sem numeração visível, preservando palavras sempre que possível; cada parte mantém confirmação própria.": "Für eine neue Zeile. Längere Nachrichten werden automatisch ohne sichtbare Nummerierung aufgeteilt, wobei Wörter nach Möglichkeit erhalten bleiben; jeder Teil behält seine eigene Bestätigung.",
    "para selecioná-lo como destinatário e responder. Se clicar no próprio indicativo, o programa tenta selecionar o outro participante.": "Um diese Person als Empfänger auszuwählen und zu antworten, klicken Sie auf Ihren eigenen Button. Das Programm versucht dann, den anderen Teilnehmer auszuwählen.",
