    "Plataforma": "Plattform",
    "podem ser informadas em decimal ou graus/minutos/segundos. Na primeira execução, o cliente solicita a localização ao navegador/SO para pré-preencher as coordenadas e centralizar o mapa. O botão": "Die Werte können als Dezimalzahlen oder in Grad/Minuten/Sekunden eingegeben werden. Beim ersten Start fordert der Client den Standort vom Browser/Betriebssystem an, um die Koordinaten vorab einzutragen und die Karte zu zentrieren. Die Schaltfläche",
