    "publicada.": "Veröffentlicht.",
    "PY2AAA-9, PU2BBB-7, PT2CCC": "PY2AAA-9, PU2BBB-7, PT2CCC",
    "Quando chega uma nova mensagem para sua estação e a aba Mensagens já está aberta, o programa usa um aviso pequeno e não bloqueante, que fecha automaticamente pelo tempo definido em Configuração. Fora da aba Mensagens, permanece o aviso completo com opção de responder.": "Wenn eine neue Nachricht für Ihren Sender eingeht und der Nachrichten-Tab bereits geöffnet ist, verwendet das Programm eine kleine, nicht blockierende Benachrichtigung, die sich nach der in den Einstellungen festgelegten Zeit automatisch schließt. Außerhalb des Nachrichten-Tabs bleibt die vollständige Benachrichtigung mit der Möglichkeit zum Antworten erhalten.",
    "Quando houver atualização, clicar no aviso inicia o download do pacote compatível com a plataforma. O arquivo é validado antes da instalação.": "Wenn ein Update verfügbar ist, startet ein Klick auf die Benachrichtigung den Download des mit Ihrer Plattform kompatiblen Pakets. Die Datei wird vor der Installation geprüft.",
    "Quando houver nova versão, o cliente seleciona o pacote compatível com a plataforma, valida o download e usa um updater auxiliar para encerrar a versão atual, instalar e abrir a nova versão.": "Wenn eine neue Version verfügbar ist, wählt der Client das mit der Plattform kompatible Paket aus, validiert den Download und verwendet ein Hilfsaktualisierungsprogramm, um die aktuelle Version zu schließen, die neue Version zu installieren und zu öffnen.",
    "quando necessário. A configuração oferece sugestões regionais e continua aceitando servidor manual.": "Bei Bedarf bietet die Konfiguration Vorschläge für die Region TECH0__ und akzeptiert weiterhin manuelle Servereinstellungen.",
    "quando usado pela serial neste fluxo, mantenha o rádio no modo": "Bei Verwendung der seriellen Kommunikation in diesem Datenstrom muss das Funkgerät im Modus „Modus“ bleiben.",
