    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "Le nuove installazioni utilizzano di default i prefissi brasiliani. L'editor grafico consente di combinare filtri per Brasile, raggio, area geografica, prefissi, nominativi esatti e tipi di pacchetto, mantenendo sempre disponibile il campo per l'inserimento manuale.",
    "novo": "nuovo",
    "Novo destinatário: __ARG0__. Ainda não há conversa registrada com este indicativo.": "Nuovo destinatario: __ARG0__. Non ci sono ancora conversazioni registrate con questo indirizzo.",
    "O aplicativo continua ativo enquanto os indicadores são preparados.": "L'applicazione rimane attiva durante la preparazione degli indicatori.",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Il file esportato contiene il codice di accesso APRS-IS in formato leggibile. Conservalo in un luogo sicuro.",
    "O banco SQLite fica em:": "Il database SQLite si trova in:",
    "O botão": "Il pulsante",
    "O cabeçalho informa se você está usando a": "L'intestazione ti dice se stai usando il",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "Il client non assegna un modello radio basandosi esclusivamente sul chipset USB. Quando Windows non segnala il modello effettivo, l'interfaccia viene visualizzata in modo generico, ad esempio.",
    "O compositor aceita mensagens longas. Use": "Il compositore accetta messaggi lunghi. Utilizzare",
    "O destino deixou de possuir rota RF completa no período selecionado.": "La destinazione non dispone più di un percorso RF completo durante il periodo selezionato.",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi utilizza la soppressione dei duplicati, il blocco dei cicli, la limitazione dei salti e una coda di priorità per i messaggi/ACK/REJ.",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "Il filtro APRS-IS è vuoto. A seconda del server e della porta utilizzati, il client potrebbe ricevere un volume di traffico molto più elevato, incluso l'intero flusso disponibile su questa connessione.\n\nSi desidera continuare senza filtro?",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "Il grafico utilizza messaggi, ACK/REJ, e presenza, RF, per dare priorità al traffico utile ed evitare ripetizioni non necessarie. Non riscrive arbitrariamente percorsi di terze parti né inventa collegamenti, RF.",
    "O idioma é aplicado imediatamente à interface.": "Il linguaggio viene applicato immediatamente a interface.",
    "O início precisa ser anterior ao fim.": "L'inizio deve precedere la fine.",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "Il programma di installazione e il file EXE portatile utilizzano lo stesso database locale.",
    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Il file JSON esportato contiene il codice di accesso APRS-IS in formato leggibile. Conservalo in un luogo sicuro.",
    "O novo cálculo falhou; mantendo o último ranking válido.": "Il nuovo calcolo non è riuscito; la classifica precedente rimane valida.",
    "O pacote compatível será baixado, validado e instalado automaticamente.": "Il pacchetto compatibile verrà scaricato, convalidato e installato automaticamente.",
    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "Lo standard per le nuove installazioni prevede identificatori brasiliani. Il campo rimane completamente modificabile per i filtri APRS-IS manuais.",
    "O passcode é mascarado no Log.": "Il codice di accesso è mascherato nel registro.",
