    "podem ser informadas em decimal ou graus/minutos/segundos. Na primeira execução, o cliente solicita a localização ao navegador/SO para pré-preencher as coordenadas e centralizar o mapa. O botão": "I valori possono essere inseriti in decimale o in gradi/minuti/secondi. Al primo avvio, il client richiede la posizione dal browser/OS per precompilare le coordinate e centrare la mappa. Il pulsante",
