    "Se o filtro ficar vazio, o programa pede confirmação antes de salvar e explica o impacto potencial no volume de tráfego.": "Se il filtro viene lasciato vuoto, il programma richiede conferma prima di salvare e spiega il potenziale impatto sul volume di traffico.",
