    ", informe seu indicativo, SSID, posição e parâmetros APRS-IS. O passcode é calculado automaticamente a partir do indicativo-base.": "コールサイン（SSID）、位置情報、およびパラメータ（APRS-IS）を入力してください。パスコードはベースコールサインから自動的に計算されます。",
    ", porta": "ドア",
    ", revise o campo de filtro APRS-IS. Um texto livre como": "フィルターフィールド APRS-IS を確認してください。自由テキスト例:",
    ". Campo livre para servidores personalizados.": "カスタムサーバー用の自由フィールド。",
    ". O path RF personalizado aceita valores como": "カスタムパス RF は、次のような値を受け入れます。",
    ". Quando o trace retornar um caminho e houver posições conhecidas, os hops são destacados temporariamente no mapa; hops sem posição continuam indicados na resposta sem localização inventada.": "トレースが経路を返し、既知の位置情報がある場合、ホップは一時的にマップ上で強調表示されます。位置情報のないホップは、想定される位置情報がないまま応答に示されます。",
