    "A alteração é aplicada imediatamente e fica salva após clicar em Salvar.": "変更は即座に適用され、「保存」をクリックすると保存されます。",
    "A altitude ainda está em 0 m porque não foi obtida automaticamente. O beacon será enviado, mas recomendamos informar a altitude real.": "高度は自動的に取得されなかったため、0mのままです。ビーコンは送信されますが、実際の高度を報告することをお勧めします。",
    "A atualização está em andamento. Aguarde a conclusão.": "アップデート処理中です。完了するまでしばらくお待ちください。",
    "A cadeia representa alcançabilidade RF histórica composta por enlaces observados individualmente e compatíveis pelas coordenadas dos nós.": "この連鎖は、個別に観測され、ノードの座標によって互換性のあるリンクから構成される、過去の到達可能性を表しています。",
    "A camada mostra apenas terreno com altitude igual ou superior à cota escolhida no slider.": "このレイヤーには、スライダーで選択した標高以上の標高を持つ地形のみが表示されます。",
    "A lista mostra indicativo, última recepção, distância, velocidade, curso, altitude e informações conhecidas.": "リストには、コールサイン、最終受信時刻、距離、速度、進路、高度、および既知の情報が表示されます。",
    "A malha é muito densa e a busca atingiu o limite de segurança. Os enlaces elegíveis continuam visíveis; refine o período se precisar de mais rotas.": "ネットワーク密度が非常に高く、検索が安全限界に達しました。有効なリンクは引き続き表示されます。より多くの経路が必要な場合は、期間を絞り込んでください。",
    "A mensagem já está sendo colocada na fila.": "メッセージは既にキューに追加されています。",
    "A string contém componentes ainda não representados no editor. Eles serão preservados enquanto você não gerar uma nova string.": "この文字列には、エディタにまだ表示されていない要素が含まれています。これらの要素は、新しい文字列を生成するまで保持されます。",
    "A topologia oferece período": "位相幾何学は周期性を提供する。",
