    "Alterações de transporte reconectam o TNC se ele já estiver em uso. Ativar funções de TX exige a confirmação explícita acima.": "トランスポートの変更により、TNCが既に使用されている場合は再接続されます。TX機能を有効にするには、上記で明示的な確認が必要です。",
