    "Monte os componentes abaixo e gere a string APRS-IS automaticamente.": "以下のコンポーネントを組み立てて、文字列「APRS-IS」を自動的に生成してください。",
    "mostra apenas mensagens individuais de ou para o seu": "個々のメッセージのみを表示します。",
    "Motivo": "理由",
    "Na aba": "タブで",
    "Na primeira execução, quando a permissão é concedida, o mapa é centralizado na localização atual do usuário. Depois disso, a posição e o zoom escolhidos manualmente ficam salvos localmente e não são recentralizados continuamente.": "初回実行時、権限が付与されると、地図はユーザーの現在位置を中心に表示されます。その後は、手動で選択した位置とズームレベルがローカルに保存され、継続的に再設定されることはありません。",
