    "Nova versão v__ARG0__ disponível": "新バージョンv__ARG0__が利用可能です",
    "Novas estações": "新駅",
    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "新規インストールでは、デフォルトでブラジルのプレフィックスが使用されます。グラフィカルエディタでは、ブラジル、半径、地理的エリア、プレフィックス、正確なコールサイン、パケットタイプなどのフィルタを組み合わせることができ、手動入力フィールドは常に利用可能です。",
    "novo": "新しい",
    "Novo destinatário: __ARG0__. Ainda não há conversa registrada com este indicativo.": "新しい受信者：__ARG0__。このアドレスとの会話記録はまだありません。",
    "O aplicativo continua ativo enquanto os indicadores são preparados.": "指標の準備中も、アプリケーションはアクティブな状態を維持します。",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "エクスポートされたファイルには、パスコード「APRS-IS」が判読可能なテキスト形式で含まれています。安全な場所に保管してください。",
    "O banco SQLite fica em:": "SQLiteデータベースは以下の場所にあります。",
    "O botão": "ボタン",
    "O cabeçalho informa se você está usando a": "ヘッダーには、",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "クライアントは、USBチップセットのみに基づいて無線モデルを割り当てません。Windowsが実際のモデルを報告しない場合、インターフェースは汎用的に表示されます。",
    "O compositor aceita mensagens longas. Use": "作曲者は長いメッセージを受け付けます。",
    "O destino deixou de possuir rota RF completa no período selecionado.": "選択した期間中、目的地には完全な RF ルートが存在しません。",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digiは、メッセージ/ACK/REJに対して、重複抑制、ループブロッキング、ホップ制限、および優先度キューを使用します。",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "APRS-IS フィルタは空です。使用するサーバーとポートによっては、クライアントは、この接続で利用可能なすべてのトラフィックを含む、はるかに大量のトラフィックを受信する可能性があります。\n\nフィルタを使用せずに続行しますか？",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "このグラフは、メッセージ（ACK/REJ）とプレゼンス（RF）を使用して、有用なトラフィックを優先し、不要な繰り返しを回避します。サードパーティのパスを恣意的に書き換えたり、リンク（RF）を生成したりすることはありません。",
    "O idioma é aplicado imediatamente à interface.": "この言語は、interface に即座に適用されます。",
    "O início precisa ser anterior ao fim.": "終わりの前には始まりがなければならない。",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "インストーラーとポータブルEXEファイルは、同じローカルデータベースを使用します。",
