    "A alteração é aplicada imediatamente e fica salva após clicar em Salvar.": "Zmiana zostanie zastosowana natychmiast i zapisana po kliknięciu przycisku Zapisz.",
    "A altitude ainda está em 0 m porque não foi obtida automaticamente. O beacon será enviado, mas recomendamos informar a altitude real.": "Wysokość nadal wynosi 0 m, ponieważ nie została uzyskana automatycznie. Sygnał radiolatarni zostanie wysłany, ale zalecamy podanie rzeczywistej wysokości.",
    "A atualização está em andamento. Aguarde a conclusão.": "Aktualizacja jest w toku. Poczekaj na jej zakończenie.",
    "A cadeia representa alcançabilidade RF histórica composta por enlaces observados individualmente e compatíveis pelas coordenadas dos nós.": "Łańcuch reprezentuje historyczną dostępność składającą się z połączeń obserwowanych indywidualnie i zgodnych ze współrzędnymi węzłów.",
    "A camada mostra apenas terreno com altitude igual ou superior à cota escolhida no slider.": "Warstwa ta wyświetla tylko teren o wysokości równej lub większej od wysokości wybranej za pomocą suwaka.",
    "A lista mostra indicativo, última recepção, distância, velocidade, curso, altitude e informações conhecidas.": "Lista zawiera znak wywoławczy, ostatnio odebrany sygnał, odległość, prędkość, kurs, wysokość i znane informacje.",
    "A malha é muito densa e a busca atingiu o limite de segurança. Os enlaces elegíveis continuam visíveis; refine o período se precisar de mais rotas.": "Sieć jest bardzo gęsta, a wyszukiwanie osiągnęło bezpieczny limit. Odpowiednie linki pozostają widoczne; doprecyzuj okres, jeśli potrzebujesz więcej tras.",
