    "Na aba": "W zakładce",
    "Na primeira execução, quando a permissão é concedida, o mapa é centralizado na localização atual do usuário. Depois disso, a posição e o zoom escolhidos manualmente ficam salvos localmente e não são recentralizados continuamente.": "Podczas pierwszego uruchomienia, po udzieleniu zgody, mapa jest wyśrodkowana na bieżącej lokalizacji użytkownika. Następnie ręcznie wybrana pozycja i powiększenie są zapisywane lokalnie i nie są stale zmieniane.",
