    "podem ser informadas em decimal ou graus/minutos/segundos. Na primeira execução, o cliente solicita a localização ao navegador/SO para pré-preencher as coordenadas e centralizar o mapa. O botão": "Wartości można wprowadzać w systemie dziesiętnym lub w stopniach/minutach/sekundach. Podczas pierwszego uruchomienia klient żąda od przeglądarki/systemu operacyjnego podania lokalizacji, aby wstępnie wypełnić współrzędne i wyśrodkować mapę. Przycisk",
