    "A alteração é aplicada imediatamente e fica salva após clicar em Salvar.": "De wijziging wordt direct toegepast en opgeslagen na het klikken op 'Opslaan'.",
    "A altitude ainda está em 0 m porque não foi obtida automaticamente. O beacon será enviado, mas recomendamos informar a altitude real.": "De hoogte staat nog steeds op 0 m omdat deze niet automatisch is verkregen. Het baken zal worden verzonden, maar we raden aan de werkelijke hoogte door te geven.",
    "A atualização está em andamento. Aguarde a conclusão.": "De update wordt momenteel uitgevoerd. Wacht alstublieft tot deze is voltooid.",
    "A cadeia representa alcançabilidade RF histórica composta por enlaces observados individualmente e compatíveis pelas coordenadas dos nós.": "De keten vertegenwoordigt de historische bereikbaarheid, samengesteld uit afzonderlijk waargenomen schakels die compatibel zijn op basis van de coördinaten van de knooppunten.",
    "A camada mostra apenas terreno com altitude igual ou superior à cota escolhida no slider.": "De laag toont alleen terrein met een hoogte die gelijk is aan of groter is dan de hoogte die in de schuifregelaar is geselecteerd.",
    "A lista mostra indicativo, última recepção, distância, velocidade, curso, altitude e informações conhecidas.": "De lijst toont de roepnaam, laatst ontvangen datum, afstand, snelheid, koers, hoogte en bekende informatie.",
    "A malha é muito densa e a busca atingiu o limite de segurança. Os enlaces elegíveis continuam visíveis; refine o período se precisar de mais rotas.": "Het netwerk is erg dicht en de zoekopdracht heeft de veiligheidslimiet bereikt. Relevante verbindingen blijven zichtbaar; verfijn de periode als u meer routes nodig heeft.",
