    "Na primeira execução, quando a permissão é concedida, o mapa é centralizado na localização atual do usuário. Depois disso, a posição e o zoom escolhidos manualmente ficam salvos localmente e não são recentralizados continuamente.": "Bij de eerste keer opstarten, wanneer toestemming is verleend, wordt de kaart gecentreerd op de huidige locatie van de gebruiker. Daarna worden de handmatig geselecteerde positie en zoomniveau lokaal opgeslagen en niet continu opnieuw ingesteld.",
