    "novas instalações usam por padrão os prefixos brasileiros. O editor gráfico pode combinar filtro Brasil, raio, área geográfica, prefixos, indicativos exatos e tipos de pacote, mantendo o campo manual sempre disponível.": "Nieuwe installaties gebruiken standaard Braziliaanse prefixen. De grafische editor kan filters combineren voor Brazilië, straal, geografisch gebied, prefixen, exacte roepnamen en pakkettypen, terwijl het handmatige veld altijd beschikbaar blijft.",
    "novo": "nieuw",
    "Novo destinatário: __ARG0__. Ainda não há conversa registrada com este indicativo.": "Nieuwe ontvanger: __ARG0__. Er zijn nog geen gesprekken met dit adres geregistreerd.",
    "O aplicativo continua ativo enquanto os indicadores são preparados.": "De applicatie blijft actief terwijl de indicatoren worden voorbereid.",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Het geëxporteerde bestand bevat de toegangscode APRS-IS in leesbare tekst. Bewaar het op een veilige plaats.",
    "O banco SQLite fica em:": "De SQLite-database bevindt zich op:",
    "O botão": "De knop",
    "O cabeçalho informa se você está usando a": "De koptekst geeft aan of je de gebruikt",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "De client wijst geen radiomodel toe op basis van alleen de USB-chipset. Als Windows het daadwerkelijke model niet rapporteert, wordt de interface bijvoorbeeld generiek weergegeven.",
    "O compositor aceita mensagens longas. Use": "De editor accepteert lange berichten. Gebruik",
    "O destino deixou de possuir rota RF completa no período selecionado.": "De bestemming heeft gedurende de geselecteerde periode geen complete RF-route meer.",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi gebruikt duplicatieonderdrukking, lusblokkering, hopbeperking en een prioriteitswachtrij voor berichten/ACK/REJ.",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "Het APRS-IS-filter is leeg. Afhankelijk van de gebruikte server en poort kan de client een veel hoger verkeersvolume ontvangen, inclusief de volledige beschikbare bandbreedte op deze verbinding.\n\nWilt u doorgaan zonder filter?",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "De grafiek gebruikt berichten, ACK/REJ, en aanwezigheid, RF, om nuttig verkeer te prioriteren en onnodige herhaling te voorkomen. Het herschrijft niet willekeurig paden van derden en verzint geen links, RF.",
    "O idioma é aplicado imediatamente à interface.": "De taal wordt direct toegepast op interface.",
    "O início precisa ser anterior ao fim.": "Het begin moet vóór het einde komen.",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "Het installatieprogramma en het draagbare uitvoerbare bestand gebruiken dezelfde lokale database.",
    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "Het geëxporteerde bestand JSON bevat de toegangscode APRS-IS in leesbare tekst. Bewaar het op een veilige plaats.",
    "O novo cálculo falhou; mantendo o último ranking válido.": "De nieuwe berekening is mislukt; de laatste rangschikking blijft geldig.",
    "O pacote compatível será baixado, validado e instalado automaticamente.": "Het compatibele pakket wordt automatisch gedownload, gevalideerd en geïnstalleerd.",
    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "De standaard voor nieuwe installaties ontvangt Braziliaanse identificatiecodes. Het veld blijft volledig bewerkbaar voor filters APRS-IS manuais.",
    "O passcode é mascarado no Log.": "De toegangscode is in het logboek gemaskeerd.",
    "o popup da estação inclui atalhos para consultar": "Het pop-upvenster van het station bevat snelkoppelingen naar verschillende pagina's.",
