    "para não impedir a conexão e mostra um aviso recomendando informar a altitude real.": "Om de verbinding niet te verstoren, wordt een waarschuwing weergegeven waarin wordt aangeraden uw werkelijke hoogte in te voeren.",
    "para nova linha. Mensagens maiores são divididas automaticamente sem numeração visível, preservando palavras sempre que possível; cada parte mantém confirmação própria.": "Voor een nieuwe regel. Grotere berichten worden automatisch gesplitst zonder zichtbare nummering, waarbij woorden zoveel mogelijk behouden blijven; elk deel behoudt zijn eigen bevestiging.",
