    "podem ser informadas em decimal ou graus/minutos/segundos. Na primeira execução, o cliente solicita a localização ao navegador/SO para pré-preencher as coordenadas e centralizar o mapa. O botão": "De waarden kunnen worden ingevoerd in decimale vorm of in graden/minuten/seconden. Bij de eerste keer opstarten vraagt ​​de client de locatie op bij de browser/het besturingssysteem om de coördinaten vooraf in te vullen en de kaart te centreren. De knop",
