    "publicada.": "Gepubliceerd.",
    "PY2AAA-9, PU2BBB-7, PT2CCC": "PY2AAA-9, PU2BBB-7, PT2CCC",
    "Quando chega uma nova mensagem para sua estação e a aba Mensagens já está aberta, o programa usa um aviso pequeno e não bloqueante, que fecha automaticamente pelo tempo definido em Configuração. Fora da aba Mensagens, permanece o aviso completo com opção de responder.": "Wanneer er een nieuw bericht voor uw station binnenkomt en het tabblad Berichten al geopend is, gebruikt het programma een kleine, niet-blokkerende melding die automatisch sluit na de in de instellingen ingestelde tijd. Buiten het tabblad Berichten blijft de volledige melding zichtbaar, inclusief de mogelijkheid om te reageren.",
    "Quando houver atualização, clicar no aviso inicia o download do pacote compatível com a plataforma. O arquivo é validado antes da instalação.": "Wanneer er een update beschikbaar is, start het downloaden van het pakket dat compatibel is met uw platform door op de melding te klikken. Het bestand wordt gevalideerd voordat het wordt geïnstalleerd.",
    "Quando houver nova versão, o cliente seleciona o pacote compatível com a plataforma, valida o download e usa um updater auxiliar para encerrar a versão atual, instalar e abrir a nova versão.": "Wanneer een nieuwe versie beschikbaar is, selecteert de klant het pakket dat compatibel is met het platform, valideert de download en gebruikt een hulpprogramma om de huidige versie te sluiten, de nieuwe versie te installeren en te openen.",
    "quando necessário. A configuração oferece sugestões regionais e continua aceitando servidor manual.": "indien nodig. De configuratie biedt suggesties voor regionais en blijft handmatige serverinstellingen accepteren.",
    "quando usado pela serial neste fluxo, mantenha o rádio no modo": "Houd de radio in de modus wanneer u seriële communicatie in deze stream gebruikt.",
