    "Ranking único de estações comuns. Telemetria, iGates e digipeaters são excluídos; interações consideram somente conversas APRS manuais.": "Enkelvoudige rangschikking van gemeenschappelijke stations. Telemetrie, iGates en digipeaters zijn uitgesloten; interacties houden alleen rekening met APRS en ais gesprekken.",
