    "O aplicativo continua ativo enquanto os indicadores são preparados.": "在指标准备期间，应用程序将保持运行状态。",
    "O arquivo exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "导出的文件包含密码 APRS-IS，以可读文本形式呈现。请妥善保管。",
