    "O cabeçalho informa se você está usando a": "标题会告诉你你是否正在使用",
    "O Client não atribui um modelo de rádio apenas pelo chipset USB. Quando o Windows não informar o modelo real, a interface é mostrada de forma genérica, por exemplo": "客户端不会仅根据 USB 芯片组来分配无线电型号。例如，当 Windows 未报告实际型号时，界面将显示为通用信息。",
    "O compositor aceita mensagens longas. Use": "作曲家接受长消息。使用",
    "O destino deixou de possuir rota RF completa no período selecionado.": "在选定的时间段内，目的地不再有完整的 RF 路线。",
    "O digi usa supressão de duplicatas, bloqueio de loop, limite de hops e fila com prioridade para mensagens/ACK/REJ.": "Digi 使用重复抑制、循环阻塞、跳数限制和消息优先级队列/ACK/REJ。",
    "O filtro APRS-IS está vazio. Dependendo do servidor e da porta utilizados, o cliente poderá receber um volume muito maior de tráfego, inclusive todo o fluxo disponibilizado nessa conexão.\n\nDeseja continuar sem filtro?": "APRS-IS 过滤器为空。根据所使用的服务器和端口，客户端可能会接收到更大的流量，包括此连接上的所有可用流量。\n\n是否要在不使用过滤器的情况下继续？",
    "O grafo usa mensagens, ACK/REJ e presença RF para priorizar tráfego útil e evitar repetição desnecessária. Ele não reescreve arbitrariamente paths de terceiros nem inventa enlaces RF.": "该图使用消息（ACK/REJ）和存在状态（RF）来优先处理有用的流量并避免不必要的重复。它不会随意重写第三方路径或创建链接（RF）。",
    "O idioma é aplicado imediatamente à interface.": "该语言立即应用于 interface。",
    "O início precisa ser anterior ao fim.": "开始必须先于结束。",
    "O instalador e o Portable EXE usam esse mesmo banco local.": "安装程序和便携版 EXE 使用同一个本地数据库。",
    "O JSON exportado contém o passcode APRS-IS em texto legível. Guarde-o em local seguro.": "导出的JSON文件包含以可读文本形式显示的密码APRS-IS。请将其妥善保管。",
    "O novo cálculo falhou; mantendo o último ranking válido.": "新的计算失败；之前的排名仍然有效。",
    "O pacote compatível será baixado, validado e instalado automaticamente.": "兼容的软件包将自动下载、验证和安装。",
    "O padrão de novas instalações recebe indicativos brasileiros. O campo continua totalmente editável para filtros APRS-IS manuais.": "新安装的标准采用巴西标识符。该字段对于过滤器APRS-IS manuais仍然完全可编辑。",
    "O passcode é mascarado no Log.": "日志中已对密码进行屏蔽。",
